/* Local WebGL garment preview using the supplied TREFF NIX front/back photo.
   Side surfaces are interpolated: this is a design preview, not a production model. */
(() => {
  const canvas = document.getElementById('shirt-360');
  if (!canvas) return;
  const gl = canvas.getContext('webgl', {alpha: true, antialias: true});
  if (!gl) return;
  const shader = (type, source) => {
    const s = gl.createShader(type); gl.shaderSource(s, source); gl.compileShader(s);
    if (!gl.getShaderParameter(s, gl.COMPILE_STATUS)) throw new Error('Shader');
    return s;
  };
  try {
    const program = gl.createProgram();
    gl.attachShader(program, shader(gl.VERTEX_SHADER, `
      attribute vec3 position; attribute vec2 uv;
      uniform float angle; uniform float aspect;
      varying vec2 textureUV; varying float light;
      void main() {
        float c=cos(angle), s=sin(angle);
        vec3 p=vec3(c*position.x+s*position.z,position.y,-s*position.x+c*position.z);
        float perspective=3.8/(3.8-p.z);
        gl_Position=vec4(p.x*perspective*0.78/aspect,p.y*perspective*0.78,-p.z*0.15,1.0);
        textureUV=uv; light=0.83+0.17*abs(c);
      }`));
    gl.attachShader(program, shader(gl.FRAGMENT_SHADER, `
      precision mediump float; uniform sampler2D photo;
      varying vec2 textureUV; varying float light;
      void main(){ vec4 color=texture2D(photo,textureUV); if(color.a<0.35) discard; gl_FragColor=vec4(color.rgb*light,color.a); }
    `));
    gl.linkProgram(program);
    if (!gl.getProgramParameter(program, gl.LINK_STATUS)) return;
    gl.useProgram(program);
    // Cross sections follow the silhouette in the supplied photograph (1000 px wide).
    const rows = [
      [118,201,343,659,826], [145,186,357,640,843],
      [169,155,389,609,873], [210,57,489,538,941],
      [270,33,513,518,962], [335,19,531,505,979],
      [399,10,548,499,990], [424,105,438,566,907],
      [475,112,431,568,906], [550,111,430,565,909],
      [650,102,439,558,915], [745,95,446,553,922],
      [792,91,450,549,924], [817,146,400,586,890], [845,149,398,588,887]
    ];
    const segments=48, vertices=[], indices=[];
    rows.forEach(([y,fl,fr,bl,br]) => {
      for (let k=0;k<=segments;k++) {
        const phi=2*Math.PI*k/segments, x=Math.cos(phi), z=Math.sin(phi);
        const front=z>=0;
        const width=(fr-fl)/2;
        const depth=(y<170?28:y<424?47:58);
        const imageX=front?(fl+(x+1)*(fr-fl)/2):(bl+(1-x)*(br-bl)/2);
        vertices.push(x*width/450,(468-y)/450,z*depth/450,Math.max(0.015,Math.min(0.985,imageX/1000)),Math.max(0.015,Math.min(0.985,y/(1199/1312*1000))));
      }
    });
    for(let j=0;j<rows.length-1;j++) for(let k=0;k<segments;k++) {
      const a=j*(segments+1)+k,b=a+segments+1;
      indices.push(a,b,a+1,a+1,b,b+1);
    }
    const buffer=gl.createBuffer(); gl.bindBuffer(gl.ARRAY_BUFFER,buffer);
    gl.bufferData(gl.ARRAY_BUFFER,new Float32Array(vertices),gl.STATIC_DRAW);
    for(const [name,size,offset] of [['position',3,0],['uv',2,12]]) {
      const loc=gl.getAttribLocation(program,name);gl.enableVertexAttribArray(loc);gl.vertexAttribPointer(loc,size,gl.FLOAT,false,20,offset);
    }
    const ib=gl.createBuffer();gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER,ib);gl.bufferData(gl.ELEMENT_ARRAY_BUFFER,new Uint16Array(indices),gl.STATIC_DRAW);
    const texture=gl.createTexture();gl.bindTexture(gl.TEXTURE_2D,texture);
    gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_S,gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_T,gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MIN_FILTER,gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MAG_FILTER,gl.LINEAR);
    gl.enable(gl.DEPTH_TEST);gl.clearColor(0,0,0,0);
    const aLoc=gl.getUniformLocation(program,'angle'), aspectLoc=gl.getUniformLocation(program,'aspect');
    const motion=window.matchMedia('(prefers-reduced-motion: reduce)');
    let paused=motion.matches, angle=0, last=0, frame=0, dragging=false, previousX=0;
    let completedTurns=0, currentDesign='';
    function cleanTexture(image){
      const c=document.createElement('canvas');c.width=image.naturalWidth;c.height=image.naturalHeight;
      const ctx=c.getContext('2d',{willReadFrequently:true});ctx.drawImage(image,0,0);
      const d=ctx.getImageData(0,0,c.width,c.height),a=d.data,w=c.width,h=c.height;
      // Remove only near-neutral background connected to the outer border, not shirt artwork.
      const seen=new Uint8Array(w*h),queue=new Int32Array(w*h);let head=0,tail=0;
      function test(i){if(i<0||i>=w*h||seen[i])return;const k=i*4,r=a[k],g=a[k+1],b=a[k+2];
        if(Math.max(r,g,b)-Math.min(r,g,b)>17||r<90||r>248)return;
        seen[i]=1;queue[tail++]=i;}
      for(let x=0;x<w;x++){test(x);test((h-1)*w+x)}
      for(let y=0;y<h;y++){test(y*w);test(y*w+w-1)}
      while(head<tail){const i=queue[head++],x=i%w;if(x)test(i-1);if(x<w-1)test(i+1);if(i>=w)test(i-w);if(i<(h-1)*w)test(i+w)}
      for(let i=0;i<w*h;i++)if(seen[i])a[i*4+3]=0;
      ctx.putImageData(d,0,0);return c;
    }
    function updateDesign() {
      const link=document.getElementById('shirt-preview-link');
      const src=link && link.getAttribute('href');
      if(!src || src===currentDesign) return;
      const next=new Image();
      next.onload=()=>{
        gl.bindTexture(gl.TEXTURE_2D,texture);
        try { gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA,gl.RGBA,gl.UNSIGNED_BYTE,cleanTexture(next));currentDesign=src; } catch(_) {}
      };
      next.src=src;
    }
    const draw=(now)=>{
      const delta=last?Math.min(now-last,60):0;last=now;
      if(!paused&&!document.hidden&&!dragging) angle+=delta/6000*Math.PI*2;
      const turns=Math.floor(angle/(Math.PI*2));
      if(turns>completedTurns){completedTurns=turns;updateDesign();}
      const ratio=Math.min(window.devicePixelRatio||1,2);
      const width=Math.round(canvas.clientWidth*ratio), height=Math.round(canvas.clientHeight*ratio);
      if(canvas.width!==width||canvas.height!==height){canvas.width=width;canvas.height=height;gl.viewport(0,0,width,height);}
      gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);
      gl.uniform1f(aLoc,angle);gl.uniform1f(aspectLoc,width/height);
      gl.drawElements(gl.TRIANGLES,indices.length,gl.UNSIGNED_SHORT,0);
      frame=requestAnimationFrame(draw);
    };
    const img=new Image();img.onload=()=>{
      try { gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA,gl.RGBA,gl.UNSIGNED_BYTE,cleanTexture(img)); } catch (_) { return; }
      canvas.parentElement.classList.add('rotation-ready');frame=requestAnimationFrame(draw);
    };img.src='data:image/jpeg;base64,';
    motion.addEventListener('change',()=>{paused=motion.matches;});
    canvas.addEventListener('pointerdown',e=>{dragging=true;previousX=e.clientX;canvas.setPointerCapture(e.pointerId);});
    canvas.addEventListener('pointermove',e=>{if(dragging){angle+=(e.clientX-previousX)*0.018;previousX=e.clientX;}});
    const release=()=>{dragging=false;};canvas.addEventListener('pointerup',release);canvas.addEventListener('pointercancel',release);
    canvas.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();paused=true;angle+=(e.key==='ArrowRight'?1:-1)*Math.PI/8;}});
    canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();cancelAnimationFrame(frame);canvas.parentElement.classList.remove('rotation-ready');});
  } catch (_) { /* The original front/back image remains visible as a fallback. */ }
})();
